// Trace attributes (interpreter program Wave 2 / W2.2): the per-trace
// math behind derived attribute volumes. Complex-trace family via the
// analytic signal (Hilbert transform), windowed RMS and AGC amplitude.
// Validated against scipy goldens (test-data/seismolord/attributes/,
// generated by tools/validation/seismolord/attributes/gen_attributes.py
// in the Suite repo, which self-asserts its own math before writing
// anything). Every algorithm mirrors the oracle EXACTLY — same
// zero-fill, FFT padding, unwrap and gradient conventions.
//
// Conventions:
// - Input traces are brick-store amplitudes: Float32Array of ns samples,
//   nulls = NULL_VALUE (1.0e30). Null samples are zero-filled for the
//   transforms and the corresponding OUTPUT samples are NULL_VALUE —
//   nulls never enter statistics and never leave the trace as data.
// - Analytic signal recipe (the oracle pins it): zero-fill nulls,
//   zero-pad to nfft = nextpow2(ns), scipy.signal.hilbert weighting
//   (h[0] = h[nfft/2] = 1, h[1..nfft/2-1] = 2), inverse FFT, truncate
//   to ns. Identical to scipy.signal.hilbert(x, N=nfft)[:ns].
// - Instantaneous frequency follows numpy conventions exactly:
//   np.gradient(np.unwrap(np.angle(a))) / (2*pi*dt_s) — central
//   differences inside, one-sided at the edges, unwrap period 2*pi.
// - Float64 math throughout; the brick store casts to float32 on write.
//
// Pure math, worker-safe, no I/O.

import { fft, nextPow2 } from '../../lib/fft';
import { NULL_VALUE } from './manifest';

const NULL_LIM = 1.0e29;
const isNull = (v) => Math.abs(v) > NULL_LIM;

/**
 * Analytic signal of one trace (nulls zero-filled, see recipe above).
 * @param {ArrayLike<number>} trace ns samples, nulls = NULL_VALUE
 * @returns {{re: Float64Array, im: Float64Array}} length ns
 */
export function analyticSignal(trace) {
  const ns = trace.length;
  const nfft = nextPow2(ns);
  const re = new Float64Array(nfft);
  const im = new Float64Array(nfft);
  for (let i = 0; i < ns; i++) {
    const v = trace[i];
    re[i] = isNull(v) ? 0 : v;
  }
  fft(re, im, false);
  // scipy.signal.hilbert weights: keep DC and Nyquist, double positive
  // frequencies, zero negative ones. nfft is a power of two, so even.
  const half = nfft / 2;
  for (let i = 1; i < half; i++) {
    re[i] *= 2;
    im[i] *= 2;
  }
  for (let i = half + 1; i < nfft; i++) {
    re[i] = 0;
    im[i] = 0;
  }
  fft(re, im, true);
  return { re: re.subarray(0, ns).slice(), im: im.subarray(0, ns).slice() };
}

/** np.unwrap with the default period 2*pi and discont pi, in place-safe. */
export function unwrapPhase(phase) {
  const out = Float64Array.from(phase);
  const twoPi = 2 * Math.PI;
  let correction = 0;
  for (let i = 1; i < out.length; i++) {
    const d = phase[i] - phase[i - 1];
    let dd = ((((d + Math.PI) % twoPi) + twoPi) % twoPi) - Math.PI;
    if (dd === -Math.PI && d > 0) dd = Math.PI;
    if (Math.abs(d) >= Math.PI) correction += dd - d;
    out[i] = phase[i] + correction;
  }
  return out;
}

/** np.gradient over a uniform unit grid: central inside, one-sided edges. */
export function gradient1d(y) {
  const n = y.length;
  const out = new Float64Array(n);
  if (n === 1) return out;
  out[0] = y[1] - y[0];
  out[n - 1] = y[n - 1] - y[n - 2];
  for (let i = 1; i < n - 1; i++) out[i] = (y[i + 1] - y[i - 1]) / 2;
  return out;
}

/** Write NULL_VALUE into out wherever the input sample was null. */
function maskNulls(trace, out) {
  for (let i = 0; i < trace.length; i++) {
    if (isNull(trace[i])) out[i] = NULL_VALUE;
  }
}

/**
 * Envelope (reflection strength): |analytic|.
 * @param {ArrayLike<number>} trace @param {Float32Array} out ns samples
 */
export function envelopeTrace(trace, out) {
  const { re, im } = analyticSignal(trace);
  for (let i = 0; i < trace.length; i++) out[i] = Math.hypot(re[i], im[i]);
  maskNulls(trace, out);
}

/** Instantaneous phase in degrees (-180..180]. */
export function instPhaseTrace(trace, out) {
  const { re, im } = analyticSignal(trace);
  for (let i = 0; i < trace.length; i++) {
    out[i] = (Math.atan2(im[i], re[i]) * 180) / Math.PI;
  }
  maskNulls(trace, out);
}

/**
 * Instantaneous frequency in Hz. Negative values (phase reversals /
 * low-energy zones) are kept as computed — clipping is a display choice.
 * @param {number} dtUs sample interval in microseconds
 */
export function instFrequencyTrace(trace, dtUs, out) {
  const { re, im } = analyticSignal(trace);
  const phase = new Float64Array(trace.length);
  for (let i = 0; i < trace.length; i++) phase[i] = Math.atan2(im[i], re[i]);
  const grad = gradient1d(unwrapPhase(phase));
  const scale = 1 / (2 * Math.PI * dtUs * 1e-6);
  for (let i = 0; i < trace.length; i++) out[i] = grad[i] * scale;
  maskNulls(trace, out);
}

/**
 * Sweetness = envelope / sqrt(instantaneous frequency); undefined
 * (NULL_VALUE) where the frequency is not positive.
 */
export function sweetnessTrace(trace, dtUs, out) {
  const ns = trace.length;
  const env = new Float32Array(ns);
  envelopeTrace(trace, env);
  const freq = new Float32Array(ns);
  instFrequencyTrace(trace, dtUs, freq);
  for (let i = 0; i < ns; i++) {
    if (isNull(env[i]) || isNull(freq[i]) || !(freq[i] > 0)) {
      out[i] = NULL_VALUE;
    } else {
      out[i] = env[i] / Math.sqrt(freq[i]);
    }
  }
}

/**
 * Windowed RMS amplitude: per sample, the RMS over
 * [s - halfWindow, s + halfWindow] clamped to the trace (edge windows
 * shrink), nulls excluded; all-null windows are NULL_VALUE. The same
 * windowing semantics as displayEnhance.agcGainMap, O(ns) prefix sums.
 * @param {number} halfWindow samples, >= 1
 */
export function windowedRmsTrace(trace, halfWindow, out) {
  if (!Number.isFinite(halfWindow) || halfWindow < 1) {
    throw new Error(`RMS half-window must be a positive sample count, got ${halfWindow}`);
  }
  const hw = Math.floor(halfWindow);
  const ns = trace.length;
  const sum2 = new Float64Array(ns + 1);
  const cnt = new Int32Array(ns + 1);
  for (let s = 0; s < ns; s++) {
    const v = trace[s];
    const ok = !isNull(v);
    sum2[s + 1] = sum2[s] + (ok ? v * v : 0);
    cnt[s + 1] = cnt[s] + (ok ? 1 : 0);
  }
  for (let s = 0; s < ns; s++) {
    const lo = Math.max(0, s - hw);
    const hi = Math.min(ns - 1, s + hw);
    const n = cnt[hi + 1] - cnt[lo];
    out[s] = n === 0 ? NULL_VALUE : Math.sqrt((sum2[hi + 1] - sum2[lo]) / n);
  }
  maskNulls(trace, out);
}

/**
 * AGC amplitude volume: each sample scaled by traceRms / windowRms so
 * the trace keeps its overall energy while local amplitude variation is
 * equalized — the stored-volume counterpart of the display-only AGC
 * gain map. Zero-energy windows contain only zero samples, which map
 * to 0; null samples stay NULL_VALUE.
 * @param {number} halfWindow samples, >= 1
 */
export function traceAgcTrace(trace, halfWindow, out) {
  const ns = trace.length;
  const wrms = new Float32Array(ns);
  windowedRmsTrace(trace, halfWindow, wrms);
  let sum = 0;
  let n = 0;
  for (let s = 0; s < ns; s++) {
    const v = trace[s];
    if (isNull(v)) continue;
    sum += v * v;
    n += 1;
  }
  const ref = n > 0 ? Math.sqrt(sum / n) : 0;
  for (let s = 0; s < ns; s++) {
    const v = trace[s];
    if (isNull(v)) {
      out[s] = NULL_VALUE;
    } else if (isNull(wrms[s]) || wrms[s] === 0) {
      out[s] = 0;
    } else {
      out[s] = (v * ref) / wrms[s];
    }
  }
}

/**
 * Attribute registry — one entry per derived-volume attribute. `params`
 * documents the tunables (ms so the UI is sample-rate independent);
 * makeTraceCompute converts to samples against the volume's dt.
 */
export const ATTRIBUTE_DEFS = {
  envelope: {
    key: 'envelope', label: 'Envelope (reflection strength)', unit: 'amp', params: {},
  },
  inst_phase: {
    key: 'inst_phase', label: 'Instantaneous phase', unit: 'deg', params: {},
  },
  inst_freq: {
    key: 'inst_freq', label: 'Instantaneous frequency', unit: 'Hz', params: {},
  },
  sweetness: {
    key: 'sweetness', label: 'Sweetness', unit: 'amp/√Hz', params: {},
  },
  rms: {
    key: 'rms',
    label: 'RMS amplitude',
    unit: 'amp',
    params: { windowMs: { label: 'Window length (ms)', default: 80, min: 4, max: 1000 } },
  },
  agc: {
    key: 'agc',
    label: 'AGC amplitude',
    unit: 'amp',
    params: { windowMs: { label: 'Window length (ms)', default: 500, min: 20, max: 2000 } },
  },
};

/** Window length in ms -> half-window in samples (>= 1). */
export function halfWindowSamples(windowMs, dtUs) {
  const dtMs = dtUs / 1000;
  if (!(windowMs > 0) || !(dtMs > 0)) {
    throw new Error(`Window ${windowMs} ms is not usable at dt ${dtMs} ms.`);
  }
  return Math.max(1, Math.round(windowMs / 2 / dtMs));
}

/**
 * Build the per-trace compute for a registry attribute.
 * @param {string} name ATTRIBUTE_DEFS key
 * @param {Object} params user params (windowMs where applicable)
 * @param {{dtUs: number}} volume sampling
 * @returns {(trace: Float32Array, out: Float32Array) => void}
 */
export function makeTraceCompute(name, params, { dtUs }) {
  const def = ATTRIBUTE_DEFS[name];
  if (!def) throw new Error(`Unknown attribute "${name}".`);
  if (!(dtUs > 0)) throw new Error(`Attribute compute needs a positive dt, got ${dtUs}.`);
  switch (name) {
    case 'envelope':
      return (trace, out) => envelopeTrace(trace, out);
    case 'inst_phase':
      return (trace, out) => instPhaseTrace(trace, out);
    case 'inst_freq':
      return (trace, out) => instFrequencyTrace(trace, dtUs, out);
    case 'sweetness':
      return (trace, out) => sweetnessTrace(trace, dtUs, out);
    case 'rms': {
      const hw = halfWindowSamples(params?.windowMs ?? def.params.windowMs.default, dtUs);
      return (trace, out) => windowedRmsTrace(trace, hw, out);
    }
    case 'agc': {
      const hw = halfWindowSamples(params?.windowMs ?? def.params.windowMs.default, dtUs);
      return (trace, out) => traceAgcTrace(trace, hw, out);
    }
    default:
      throw new Error(`Unknown attribute "${name}".`);
  }
}
